const M={PRE:"Not started",FIRST_HALF:"First half",HALF_TIME:"Half time",SECOND_HALF:"Second half",FULL_TIME:"Full time"},o={PRE:{base:0,end:0},FIRST_HALF:{base:0,end:45},HALF_TIME:{base:45,end:45},SECOND_HALF:{base:45,end:90},FULL_TIME:{base:90,end:90}},m=15,p=t=>{const s=Math.max(0,t);return`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`},E=t=>t?{...t,readAtMs:Date.now()}:null,F=(t,s)=>{if(!t)return{period:"PRE",running:!1,minute:0,stoppage:0,addedMinutes:0,display:"0'",mmss:"00:00"};const e=o[t.period]||o.PRE;if(!t.running)return{...t,stoppage:0,display:`${t.minute}'`,mmss:p(t.minute*60)};const u=Math.max(0,Math.floor((s-(t.readAtMs??s))/1e3)),d=(t.elapsedSeconds||0)+u,r=e.base+Math.floor((d-e.base*60)/60),a=Math.min(r,e.end),i=Math.max(0,r-e.end),n=Math.min(i,m);return{...t,minute:a,stoppage:n,stalled:i>m,display:n>0?`${a}+${n}'`:`${a}'`,mmss:p(d)}};export{M as P,E as s,F as t};
